/// <summary>
/// completeLocation's and confirmLocationEmpty's answer, with how many locations are left.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountLocationResponse
{
    boolean success;
    str errorCode;
    str message;
    int openTasks;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('OpenTasks')]
public int parmOpenTasks(int _value = openTasks)
{
    openTasks = _value;
    return openTasks;
}
